interface Container<out T> {
    fun get(): T
    fun contains(item: @UnsafeVariance T): Boolean // safe: only compares, never stores
}

abstract class Builder<T : Builder<T>> {
    @Suppress("UNCHECKED_CAST")
    protected fun self(): T = this as T
    fun configure(): T = self() // returns the correct concrete subtype, not Builder<*>
}

class CarBuilder : Builder<CarBuilder>() { fun withColor(c: String): CarBuilder = self() }

interface Auditable { fun auditLog(): String }

fun <T> processAuditableComparable(items: List<T>): T
    where T : Comparable<T>, T : Auditable {
    return items.maxByOrNull { it.auditLog().length } ?: items.max()
}

interface TypedBox { fun describe(): String }

class Box<T>(private val value: T, private val describer: (T) -> String) : TypedBox {
    override fun describe() = describer(value)
}

val boxes: List<TypedBox> = listOf(Box(5) { "Int: $it" }, Box("hi") { "String: $it" })

abstract class Builder<T : Builder<T>> {
    @Suppress("UNCHECKED_CAST") protected fun self() = this as T
    fun withId(id: String): T { /* set id */ return self() }
}

class CarBuilder : Builder<CarBuilder>() { fun withColor(c: String): CarBuilder = self() }

CarBuilder().withId("c1").withColor("red") // chain preserves CarBuilder type throughout

class Buffer<out T>(initial: T) {
    private var storage: T = initial // fine — private, not part of the public contract
    fun get(): T = storage // public API only exposes T in an 'out' position
    // fun set(value: T) {} // would NOT compile — public 'in' position violates covariance
}

fun printAll(list: MutableList<out Animal>) { // projected read-only for this call
    for (animal in list) println(animal.name) // fine — reading is safe
    // list.add(Cat()) // would not compile — writing isn't allowed under this projection
}

printAll(mutableListOf(Dog(), Dog())) // MutableList<Dog> accepted here

class Wrapper<T>(val value: T) {
    companion object {
        fun <T> from(value: T): Wrapper<T> = Wrapper(value) // factory-level generic, independent
    }
}

val w = Wrapper.from("hello") // type inferred purely from the factory function's own parameter

class Box<T>(private var content: T) {
    fun get(): T = content
    fun set(value: T) { content = value }
}

val intBox = Box(5)          // Box<Int>
val stringBox = Box("hello") // Box<String>, same class, different type

interface Producer<out T> { fun produce(): T }
interface Consumer<in T> { fun consume(item: T) }

val dogProducer: Producer<Dog> = object : Producer<Dog> { override fun produce() = Dog() }
val animalProducer: Producer<Animal> = dogProducer // OK — covariant

fun printSize(list: List<*>) {
    println("Size: ${list.size}") // fine — doesn't need to know T
    // list.add(...) // wouldn't compile even if it were MutableList<*>
}

printSize(listOf("a", "b"))
printSize(listOf(1, 2, 3))

class Deserializer {
    // fun <T> deserialize(json: String): T { if (... is T) } // won't compile — erased

    fun <T : Any> deserialize(json: String, clazz: KClass<T>): T =
        gson.fromJson(json, clazz.java)
}

fun <T> sortedUnique(items: List<T>): List<T>
    where T : Comparable<T>, T : Any {
    return items.distinct().sorted()
}

// Avoid:
fun process(value: Any) { val str = value as? String ?: return }

// Prefer:
fun <T : Any> process(value: T, handler: (T) -> Unit) = handler(value)

// Generic function
fun <T> List<T>.secondOrNull(): T? =
    if (size >= 2) this[1] else null

listOf(1, 2, 3).secondOrNull()      // 2 (Int?)
listOf("a").secondOrNull()           // null (String?)

// Generic class
class Stack<T> {
    private val items = mutableListOf<T>()
    fun push(item: T) = items.add(item)
    fun pop(): T = items.removeLast()
    fun peek(): T = items.last()
}

// ❌ Won't compile — type erasure
fun <T> isType(value: Any): Boolean = value is T

// ✅ Works with reified + inline
inline fun <reified T> isType(value: Any): Boolean = value is T

isType<String>("hello")  // true
isType<Int>("hello")     // false

// Practical example — type-safe parsing
inline fun <reified T> String.parse(): T = when (T::class) {
    Int::class    -> toInt() as T
    Double::class -> toDouble() as T
    Boolean::class -> toBoolean() as T
    else -> throw IllegalArgumentException()
}

"42".parse<Int>()      // 42
"true".parse<Boolean>() // true

// out — Producer (read-only)
interface Source<out T> {
    fun next(): T   // ✅ can return T
    // fun add(t: T) // ❌ can't accept T
}

// in — Consumer (write-only)
interface Sink<in T> {
    fun put(item: T)  // ✅ can accept T
    // fun get(): T   // ❌ can't return T
}

// Star projection
fun printAll(list: List<*>) {
    list.forEach { println(it) }  // each element is Any?
}

val animals: Source<Animal> = dogSource  // ✅ out allows this
